import urllib.request, urllib.parse
BASE = "http://160.202.254.160:15880/"
PROXY = {"http": "http://127.0.0.1:12001", "https": "http://127.0.0.1:12001"}
op = urllib.request.build_opener(urllib.request.ProxyHandler(PROXY))

def post(content, headers):
    data = urllib.parse.urlencode({"content": content}).encode()
    req = urllib.request.Request(BASE, data=data, headers=headers)
    with op.open(req, timeout=20) as r:
        return r.read().decode("gb18030", "replace")

hdrs = [
    ("X-Forwarded-For", "XFFMARKER1"),
    ("X-Real-IP", "REALIPMARK2"),
    ("Client-IP", "CLIENTIPMARK3"),
    ("X-Client-IP", "XCLIENTMARK4"),
]
for name, val in hdrs:
    try:
        body = post("HDRTEST-" + val, {name: val})
    except Exception as e:
        print("%-18s ERR %s" % (name, e)); continue
    idx = body.find(val)
    print("%-18s 回显=%s" % (name, idx >= 0))
    if idx >= 0:
        print("   上下文:", repr(body[max(0, idx-70):idx+90]))
